window.__votdWeek && window.__votdWeek({"week":"2028-01-31","reading":"2 Nephi 1–2","days":[{"d":"2028-01-31","ref":"2 Nephi 1:4","b":"2 Nephi","c":1,"v":4,"he":"כִּי הִנֵּה אָמַר רָאִיתִי מַרְאֶה וּבוֹ יָדַעְתִּי כִּי נֶחְרְבָה יְרוּשָׁלָיִם וְלוּ נִשְׁאַרְנוּ בִּירוּשָׁלָיִם גַּם־אֲנַחְנוּ אָבָדְנוּ׃","en":"For, behold, said he, I have seen a vision, in which I know that Jerusalem is destroyed; and had we remained in Jerusalem we should also have perished."},{"d":"2028-02-01","ref":"2 Nephi 1:14","b":"2 Nephi","c":1,"v":14,"he":"הָקִיצוּ וְקוּמוּ מֵעָפָר וְשִׁמְעוּ דִּבְרֵי אָב רוֹעֵד אֲשֶׁר שׂוֹם תָּשִׂימוּ עַצְמוֹתָיו מְהֵרָה בַּקֶּבֶר הַקַּר וְהַדּוּמָם מִמֶּנּוּ לֹא־יָשׁוּב הֵלֶךְ עוֹד יָמִים מִסְפָּר וְאֵלֵךְ בְּדֶרֶךְ כׇּל־הָאָרֶץ׃","en":"Awake! and arise from the dust, and hear the words of a trembling parent, whose limbs ye must soon lay down in the cold and silent grave, from whence no traveler can return; a few more days and I go the way of all the earth."},{"d":"2028-02-02","ref":"2 Nephi 1:15","b":"2 Nephi","c":1,"v":15,"he":"אַךְ הִנֵּה גָּאַל יְהוָה נַפְשִׁי מִשְּׁאוֹל רָאִיתִי כְבוֹדוֹ וַאֲנִי מֻקָּף לְעוֹלָם בִּזְרוֹעוֹת אַהֲבָתוֹ׃","en":"But behold, the Lord hath redeemed my soul from hell; I have beheld his glory, and I am encircled about eternally in the arms of his love."},{"d":"2028-02-03","ref":"2 Nephi 1:20","b":"2 Nephi","c":1,"v":20,"he":"וְהוּא אָמַר כַּאֲשֶׁר תִּשְׁמְרוּ מִצְוֹתַי תַּצְלִיחוּ בָאָרֶץ וְכַאֲשֶׁר לֹא תִשְׁמְרוּ מִצְוֹתַי תִּכָּרְתוּ מִלְּפָנָי׃","en":"And he hath said that: Inasmuch as ye shall keep my commandments ye shall prosper in the land; but inasmuch as ye will not keep my commandments ye shall be cut off from my presence."},{"d":"2028-02-04","ref":"2 Nephi 2:20","b":"2 Nephi","c":2,"v":20,"he":"וַיּוֹלִידוּ בָנִים אַף גַּם מִשְׁפַּחַת כׇּל־הָאָרֶץ׃","en":"And they have brought forth children; yea, even the family of all the earth."},{"d":"2028-02-05","ref":"2 Nephi 2:25","b":"2 Nephi","c":2,"v":25,"he":"נָפַל אָדָם לְמַעַן יִהְיוּ בְנֵי־הָאָדָם וּבְנֵי־הָאָדָם יֶשְׁנָם לְמַעַן תִּהְיֶה לָהֶם שִׂמְחָה׃","en":"Adam fell that men might be; and men are, that they might have joy."},{"d":"2028-02-06","ref":"2 Nephi 2:27","b":"2 Nephi","c":2,"v":27,"he":"לָכֵן בְּנֵי־הָאָדָם חׇפְשִׁים כְּפִי הַבָּשָׂר וְכׇל־דָּבָר נִתַּן לָהֶם אֲשֶׁר יוֹעִיל לָאָדָם וְחׇפְשִׁים לִבְחֹר דְּרוֹר וְחַיֵּי עוֹלָם עַל־יְדֵי הַמְּתַוֵּךְ הַגָּדוֹל לְכׇל־אָדָם אוֹ לִבְחֹר שְׁבִי וָמָוֶת כְּפִי שְׁבִי הַשָּׂטָן וְכֹחוֹ כִּי מְבַקֵּשׁ כִּי כׇּל־אָדָם יִהְיוּ אֻמְלָלִים כָּמוֹהוּ׃","en":"Wherefore, men are free according to the flesh; and all things are given them which are expedient unto man. And they are free to choose liberty and eternal life, through the great Mediator of all men, or to choose captivity and death, according to the captivity and power of the devil; for he seeketh that all men might be miserable like unto himself."}]});
